-- 044: Arnolds Park, Arnolds Park, Iowa (Carter, 2026-10-17, from RCDB;
-- 43.36548292738213, -95.1372113889467). Not in D1 before.
--   Legend          wood, Outdoor Amusement Enterprise, 6/8/1930, 63 ft;
--                   formerly Speed Hound (1930-31/32) and Giant Coaster (to 1995)
--   Little Coaster  Miler Manufacturing kiddie, 1959; formerly Rollo Coaster
--   Mad Mouse       Allan Herschell wild mouse, 7/12/2019 - 7/29/2026 (removed)
--   Toboggan        Chance Rides Toboggan, 5/16/1998 - 1998, 450 ft, 45 ft
--   Wild Mouse      B. A. Schiff wild mouse, 6/10/1958 - 1973
--   Thriller        wood, Okoboji Coaster Company, 6/1/1930 - 1948/49 (stored
--                   as 1949; SBNO to 1950), 2,500 ft, 73 ft
-- RCDB's relocations (Mad Mouse from Bell's and Joyland, Toboggan to Grand Prix
-- Amusements) are not linked yet. Safe to run twice.
INSERT INTO parks (name, lat, lon, region) SELECT 'Arnolds Park', 43.36548292738213, -95.1372113889467, 'Iowa, US' WHERE NOT EXISTS (SELECT 1 FROM parks WHERE name = 'Arnolds Park');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, laps, yr, opened, openedPrec, closed, closedPrec) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Legend', 'Arnolds Park', 'Wood', 'Outdoor Amusement Enterprise', NULL, 63, NULL, NULL, 0, NULL, 1, 1930, '1930-06-08', 'day', NULL, NULL WHERE EXISTS (SELECT 1 FROM parks WHERE name = 'Arnolds Park') AND NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Legend' AND park = 'Arnolds Park');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, laps, yr, opened, openedPrec, closed, closedPrec) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Little Coaster', 'Arnolds Park', 'Steel', 'Miler Manufacturing', 'Miler Kiddie', NULL, NULL, NULL, 0, NULL, 1, 1959, '1959', 'year', NULL, NULL WHERE EXISTS (SELECT 1 FROM parks WHERE name = 'Arnolds Park') AND NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Little Coaster' AND park = 'Arnolds Park');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, laps, yr, opened, openedPrec, closed, closedPrec) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Mad Mouse', 'Arnolds Park', 'Steel', 'Allan Herschell', 'Allan Herschell Wild Mouse', NULL, NULL, NULL, 0, NULL, 1, 2019, '2019-07-12', 'day', '2026-07-29', 'day' WHERE EXISTS (SELECT 1 FROM parks WHERE name = 'Arnolds Park') AND NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Mad Mouse' AND park = 'Arnolds Park');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, laps, yr, opened, openedPrec, closed, closedPrec) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Toboggan', 'Arnolds Park', 'Steel', 'Chance Rides', 'Chance Rides Toboggan', 45, NULL, 450, 0, NULL, 1, 1998, '1998-05-16', 'day', '1998', 'year' WHERE EXISTS (SELECT 1 FROM parks WHERE name = 'Arnolds Park') AND NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Toboggan' AND park = 'Arnolds Park');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, laps, yr, opened, openedPrec, closed, closedPrec) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Wild Mouse', 'Arnolds Park', 'Steel', 'B. A. Schiff & Associates', 'B. A. Schiff Wild Mouse', NULL, NULL, NULL, 0, NULL, 1, 1958, '1958-06-10', 'day', '1973', 'year' WHERE EXISTS (SELECT 1 FROM parks WHERE name = 'Arnolds Park') AND NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Wild Mouse' AND park = 'Arnolds Park');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, laps, yr, opened, openedPrec, closed, closedPrec) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Thriller', 'Arnolds Park', 'Wood', 'Okoboji Coaster Company', NULL, 73, NULL, 2500, 0, NULL, 1, 1930, '1930-06-01', 'day', '1949', 'year' WHERE EXISTS (SELECT 1 FROM parks WHERE name = 'Arnolds Park') AND NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Thriller' AND park = 'Arnolds Park');
INSERT OR IGNORE INTO coaster_aliases (coaster_id, former_name, note, added) SELECT id, 'Speed Hound', 'rcdb', date('now') FROM coasters WHERE name = 'Legend' AND park = 'Arnolds Park';
INSERT OR IGNORE INTO coaster_aliases (coaster_id, former_name, note, added) SELECT id, 'Giant Coaster', 'rcdb', date('now') FROM coasters WHERE name = 'Legend' AND park = 'Arnolds Park';
INSERT OR IGNORE INTO coaster_aliases (coaster_id, former_name, note, added) SELECT id, 'Rollo Coaster', 'rcdb', date('now') FROM coasters WHERE name = 'Little Coaster' AND park = 'Arnolds Park';
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.park = 'Arnolds Park' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND a.subject = c.name AND json_extract(a.detail, '$.park') = 'Arnolds Park');
